item.text:
{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Missing reporting does not establish whether repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "70% in one reported run",
          "reason": "One reported score does not show variation across runs."
        }
      ],
      "instrument_review": "MESA 14: repeated testing is unclear. MESA 16: no evidence of variation across runs is supplied."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly states that repeated testing did not occur."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "ran the evaluation exactly once",
          "reason": "A single run cannot establish stability; it also does not demonstrate instability."
        }
      ],
      "instrument_review": "MESA 14: repeated testing explicitly did not occur. MESA 16: score stability remains unestablished."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated testing under the same conditions is explicitly reported."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's definition of stability: at most two percentage points."
        }
      ],
      "instrument_review": "MESA 14: repeated testing occurred. MESA 16: the reported range supports stability for this comparison under its stated definition."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated testing occurred regardless of whether its results were favourable."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the stated stability limit of two percentage points."
        }
      ],
      "instrument_review": "MESA 14: repeated testing occurred. MESA 16: the measured variation conflicts with the report's definition of stability."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation guidance supplies no evidence that repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The additional instructions provide no findings about score stability."
        }
      ],
      "instrument_review": "MESA 22: installation instructions help describe how to run the evaluation. They do not resolve the missing repeated-testing and variation evidence relevant to MESA 14 and 16."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A solved more evaluated puzzles under the reported scoring and conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "These results do not establish a difference in general intelligence across domains."
        }
      ],
      "instrument_review": "MESA 2 and 25: the narrow comparison matches the intended use. MESA 9 and 20: grid-only findings provide insufficient coverage and evidence for a general-intelligence claim."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "The reported results support A's better performance on the evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "Stating a broad intended use does not supply evidence of general intelligence across domains."
        }
      ],
      "instrument_review": "MESA 2: the broad intended use is described. MESA 9, 20 and 25: the supplied evidence supports the grid comparison but does not justify selecting for general intelligence across domains."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone provide no demonstrated link to improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial and reported difference interval of 12 to 28 percentage points support better correctness with A in the studied workshop."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Decision correctness findings do not establish an improvement in unmeasured safety outcomes."
        }
      ],
      "instrument_review": "MESA 20: the later trial adds evidence beyond test scores for workshop decision correctness. MESA 16: the difference interval supports the comparison. MESA 25: conclusions should remain limited to correctness in the studied workshop and conditions."
    }
  ],
  "closing_note": "No instructions required clarification. Probe labels classify statements; missing evidence was distinguished from explicit contradiction, and testing was distinguished from favourable results."
}
